			}
			if carry {
				leadingCarry = true
				weight = langruntime.CheckedI32(langruntime.CheckedSignedAdd(weight, 1))
			}
		}
	}
	end := len(digits)
	for end > 0 && digits[langruntime.CheckedSubtract(end, 1)] == '0' {
